import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:firebase_auth/firebase_auth.dart';
import 'package:flutter/material.dart';
class TrainingsPage extends StatelessWidget{const TrainingsPage({super.key});@override Widget build(BuildContext context){return Scaffold(appBar:AppBar(title:const Text('Formations')),body:StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:FirebaseFirestore.instance.collection('trainings').where('active',isEqualTo:true).snapshots(),builder:(context,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());if(s.data!.docs.isEmpty)return const Center(child:Text('Aucune formation disponible.'));return ListView(padding:const EdgeInsets.all(14),children:s.data!.docs.map((d)=>Card(child:ListTile(leading:const Icon(Icons.school),title:Text('${d.data()['title']??'Formation'}'),subtitle:Text('${d.data()['description']??''}'),trailing:const Icon(Icons.arrow_forward_ios,size:16),onTap:()=>_start(context,d.id,d.data())))).toList());}));}
 Future<void> _start(BuildContext c,String id,Map<String,dynamic>d)async{final uid=FirebaseAuth.instance.currentUser?.uid;if(uid==null)return;await FirebaseFirestore.instance.collection('users').doc(uid).collection('trainingProgress').doc(id).set({'trainingId':id,'title':d['title'],'status':'started','startedAt':FieldValue.serverTimestamp()},SetOptions(merge:true));if(c.mounted)showDialog(context:c,builder:(_)=>AlertDialog(title:Text('${d['title']}'),content:Text('Formation démarrée. Les modules et l’évaluation seront enregistrés dans votre progression.'),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Fermer'))]));}}
